sketches.source:
setcpm(44/4)

// The underworld: a low drone deep beneath the earth
drone: note("[c1,g1]").slow(8).s("sawtooth").unison(3).detune(.2).lpf(250)
  .attack(4).sustain(1).release(6).gain(.28)

// A choir of shades, heard through stone
shades: note("<[c3,eb3,g3] [ab2,c3,eb3] [f2,ab2,c3] [g2,b2,d3]>").slow(2)
  .s("choir").syl("<oo oh oo ah>").occlude(.6)
  .attack(3).release(4).space("church").gain(.26)

// Water dripping into the Styx
drips: s("drip*8?0.75").pan(rand).gain(rand.range(.05, .15)).space("church")
styx: s("stream").slow(4).distance(6).lpf(800).gain(.14)

// Cerberus growls somewhere in the dark behind you
cerberus: s("engine").slow(8).lpf(300).azimuth(160).distance(4).gain(.12)

// The ferryman's bell
bell: note("<c4 ~ ~ ~ ~ ~ ~ ~>").s("sine").fm(1.5).fmh(1.41)
  .decay(6).sustain(0).release(6).space("church").gain(.14)
